1	/**
2	 * Split Payment routes
3	 *
4	 * POST /api/games/checkout-split  — host initiates a split booking + game + pays their share
5	 * GET  /api/bookings/share/:token — public: get split booking info (for invite page)
6	 * POST /api/bookings/share/:token/checkout — invitee pays their share
7	 * GET  /api/bookings/:bookingId/split-status — host/participant: see all payment statuses
8	 */
9	import { Router, type IRouter } from "express";
10	import { and, eq, ne, sql } from "drizzle-orm";
11	import {
12	  db,
13	  bookingsTable,
14	  courtsTable,
15	  facilitiesTable,
16	  gamesTable,
17	  gameParticipantsTable,
18	  userProfilesTable,
19	  userSportProfilesTable,
20	  courtBlockedSlotsTable,
21	} from "@workspace/db";
22	import { buildDayPriceMap } from "../lib/pricing";
23	
24	import { requireAuth, getCurrentUserId } from "../lib/auth";
25	import { getAuth } from "@clerk/express";
26	import { getUncachableStripeClient } from "../stripeClient";
27	import { logger } from "../lib/logger";
28	import { sendSplitBookingCreatedEmail, sendSplitPlayerJoinedEmail, sendSplitParticipantConfirmationEmail } from "../lib/email";
29	import { sendNotification } from "../lib/notify";
30	import { z } from "zod";
31	import crypto from "node:crypto";
32	
33	const router: IRouter = Router();
34	
35	// ─── Helpers ─────────────────────────────────────────────────────────────────
36	
37	function toMin(t: string): number {
38	  const [h, m] = t.split(":").map(Number);
39	  return h * 60 + m;
40	}
41	
42	function slotsBetween(startTime: string, endTime: string): string[] {
43	  const slots: string[] = [];
44	  let cur = toMin(startTime);
45	  const end = toMin(endTime);
46	  while (cur < end) {
47	    const h = Math.floor(cur / 60).toString().padStart(2, "0");
48	    const m = (cur % 60).toString().padStart(2, "0");
49	    slots.push(`${h}:${m}`);
50	    cur += 30;
51	  }
52	  return slots;
53	}
54	
55	// ─── POST /api/games/checkout-split ──────────────────────────────────────────
56	
57	const SplitCheckoutBody = z.object({
58	  courtId: z.number().int().positive(),
59	  date: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
60	  startTime: z.string().regex(/^\d{2}:\d{2}$/),
61	  endTime: z.string().regex(/^\d{2}:\d{2}$/),
62	  totalSlots: z.number().int().min(2).max(8),
63	  sport: z.string().min(1),
64	  skillLevel: z.string().optional().default("any"),
65	  description: z.string().optional(),
66	  customerName: z.string().min(1),
67	  customerEmail: z.string().email(),
68	  customerPhone: z.string().optional(),
69	  // Open match fields
70	  isPublic: z.boolean().optional().default(false),
71	  minSkillLevel: z.number().min(0).max(10).optional(),
72	  maxSkillLevel: z.number().min(0).max(10).optional(),
73	  matchType: z.enum(["casual", "competitive"]).optional().default("casual"),
74	  // Upgrade flow: link an existing casual game instead of creating a new one
75	  linkGameId: z.number().int().positive().optional(),
76	});
77	
78	router.post("/games/checkout-split", requireAuth, async (req, res): Promise<void> => {
79	  const userId = getCurrentUserId(req)!;
80	  const parsed = SplitCheckoutBody.safeParse(req.body);
81	  if (!parsed.success) {
82	    res.status(400).json({ error: parsed.error.message });
83	    return;
84	  }
85	
86	  const {
87	    courtId, date, startTime, endTime, totalSlots, sport, skillLevel, description,
88	    customerName, customerEmail, customerPhone,
89	    isPublic, minSkillLevel, maxSkillLevel, matchType,
90	    linkGameId,
91	  } = parsed.data;
92	
93	  const reqStartMin = toMin(startTime);
94	  const reqEndMin = toMin(endTime);
95	  if (reqEndMin <= reqStartMin) {
96	    res.status(400).json({ error: "endTime must be after startTime" });
97	    return;
98	  }
99	
100	  // ── Fetch court and facility ──────────────────────────────────────────────
101	  const [courtRow] = await db
102	    .select({ court: courtsTable, facility: facilitiesTable })
103	    .from(courtsTable)
104	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
105	    .where(eq(courtsTable.id, courtId));
106	
107	  if (!courtRow?.court) {
108	    res.status(404).json({ error: "Court not found" });
109	    return;
110	  }
111	
112	  const { court, facility } = courtRow;
113	
114	  // ── Server-side price calculation ─────────────────────────────────────────
115	  const defaultSlotPrice = Number(court.pricePerHour) / 2;
116	  const { priceMap } = await buildDayPriceMap(courtId, date, defaultSlotPrice);
117	
118	  const slots = slotsBetween(startTime, endTime);
119	  let courtPrice = 0;
120	  for (const slotStart of slots) {
121	    courtPrice += priceMap.get(slotStart) ?? defaultSlotPrice;
122	  }
123	
124	  const totalPrice = courtPrice;
125	  const pricePerSlot = Math.round((totalPrice / totalSlots) * 100) / 100;
126	  const durationMinutes = reqEndMin - reqStartMin;
127	
128	  // ── Conflict check ────────────────────────────────────────────────────────
129	  const conflictingBookings = await db
130	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
131	    .from(bookingsTable)
132	    .where(and(
133	      eq(bookingsTable.courtId, courtId),
134	      eq(bookingsTable.date, date),
135	      sql`${bookingsTable.status} IN ('confirmed', 'blocked', 'awaiting_players')`,
136	    ));
137	
138	  const recentPending = await db
139	    .select({ startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
140	    .from(bookingsTable)
141	    .where(and(
142	      eq(bookingsTable.courtId, courtId),
143	      eq(bookingsTable.date, date),
144	      eq(bookingsTable.status, "pending"),
145	      sql`${bookingsTable.createdAt} > NOW() - INTERVAL '15 minutes'`,
146	    ));
147	
148	  const allConflicting = [...conflictingBookings, ...recentPending];
149	  for (const b of allConflicting) {
150	    const bStart = toMin(b.startTime);
151	    const bEnd = toMin(b.endTime);
152	    if (reqStartMin < bEnd && reqEndMin > bStart) {
153	      res.status(409).json({ error: "Pasirinktas laikas užimtas", code: "SLOT_UNAVAILABLE" });
154	      return;
155	    }
156	  }
157	
158	  // Also check blocked slots
159	  const blockedSlots = await db
160	    .select({ startTime: courtBlockedSlotsTable.startTime, endTime: courtBlockedSlotsTable.endTime })
161	    .from(courtBlockedSlotsTable)
162	    .where(and(
163	      eq(courtBlockedSlotsTable.courtId, courtId),
164	      eq(courtBlockedSlotsTable.date, date),
165	    ));
166	
167	  for (const b of blockedSlots) {
168	    const bStart = toMin(b.startTime);
169	    const bEnd = toMin(b.endTime);
170	    if (reqStartMin < bEnd && reqEndMin > bStart) {
171	      res.status(409).json({ error: "Pasirinktas laikas užblokuotas", code: "SLOT_BLOCKED" });
172	      return;
173	    }
174	  }
175	
176	  // ── Create booking ────────────────────────────────────────────────────────
177	  const splitInviteToken = crypto.randomBytes(20).toString("hex");
178	  const datetime = `${date}T${startTime}:00`;
179	
180	  const [booking] = await db.insert(bookingsTable).values({
181	    courtId,
182	    bookerUserId: userId,
183	    customerName,
184	    customerEmail,
185	    customerPhone: customerPhone ?? null,
186	    date,
187	    startTime,
188	    endTime,
189	    totalPrice: String(totalPrice),
190	    status: "pending",
191	    isSplit: true,
192	    totalSlots,
193	    pricePerSlot: String(pricePerSlot),
194	    splitInviteToken,
195	  }).returning();
196	
197	  // ── Create or reuse linked game ───────────────────────────────────────────
198	  let gameId: number;
199	  if (linkGameId) {
200	    // Upgrade flow: verify the caller owns the game before linking it.
201	    const [targetGame] = await db.select().from(gamesTable).where(eq(gamesTable.id, linkGameId));
202	    if (!targetGame) {
203	      res.status(404).json({ error: "Linked game not found" });
204	      return;
205	    }
206	    if (targetGame.creatorUserId !== userId) {
207	      res.status(403).json({ error: "Forbidden" });
208	      return;
209	    }
210	    gameId = linkGameId;
211	  } else {
212	    const [newGame] = await db.insert(gamesTable).values({
213	      creatorUserId: userId,
214	      creatorName: customerName,
215	      creatorEmail: customerEmail,
216	      sport,
217	      city: facility?.city ?? "",
218	      placeName: facility?.name ?? court.name,
219	      facilityId: facility?.id ?? null,
220	      courtId,
221	      bookingId: booking.id,
222	      playersNeeded: totalSlots,
223	      skillLevel: skillLevel ?? "any",
224	      datetime,
225	      durationMinutes,
226	      description: description ?? null,
227	      status: "pending_payment",
228	      matchType: matchType ?? "casual",
229	      isPrivate: !isPublic,
230	      visibility: isPublic ? "public" : "private",
231	      minSkillLevel: isPublic ? (minSkillLevel ?? null) : null,
232	      maxSkillLevel: isPublic ? (maxSkillLevel ?? null) : null,
233	      requiresApproval: false,
234	      teamCount: 2,
235	    }).returning();
236	    gameId = newGame.id;
237	  }
238	
239	  // ── Add host as participant (pending payment) ─────────────────────────────
240	  // For the upgrade flow, update the existing host participant to track payment;
241	  // for the normal flow, insert a fresh record.
242	  let hostParticipant: typeof gameParticipantsTable.$inferSelect;
243	  if (linkGameId) {
244	    const [existing] = await db
245	      .select()
246	      .from(gameParticipantsTable)
247	      .where(and(eq(gameParticipantsTable.gameId, linkGameId), eq(gameParticipantsTable.userId, userId)));
248	    if (existing) {
249	      [hostParticipant] = await db
250	        .update(gameParticipantsTable)
251	        .set({ paymentStatus: "pending" })
252	        .where(eq(gameParticipantsTable.id, existing.id))
253	        .returning();
254	    } else {
255	      [hostParticipant] = await db.insert(gameParticipantsTable).values({
256	        gameId: linkGameId,
257	        userId,
258	        userName: customerName,
259	        userEmail: customerEmail,
260	        status: "joined",
261	        source: "join_request",
262	        paymentStatus: "pending",
263	      }).returning();
264	    }
265	  } else {
266	    [hostParticipant] = await db.insert(gameParticipantsTable).values({
267	      gameId,
268	      userId,
269	      userName: customerName,
270	      userEmail: customerEmail,
271	      status: "joined",
272	      source: "join_request",
273	      paymentStatus: "pending",
274	    }).returning();
275	  }
276	
277	  // ── Create Stripe checkout for host's share ───────────────────────────────
278	  const origin = req.get("origin") ?? req.get("host") ?? "https://korts.lt";
279	  const base = process.env.BASE_PATH ?? "";
280	  const successUrl = `${origin}${base}/booking-confirmed?id=${booking.id}&split=1`;
281	  const cancelUrl = `${origin}${base}/courts/${courtId}?booking_cancelled=1&bookingId=${booking.id}`;
282	
283	  let checkoutUrl: string;
284	
285	  try {
286	    const stripe = await getUncachableStripeClient();
287	
288	    // Resolve Connect account
289	    let connectAccountId: string | null = null;
290	    if (facility?.ownerUserId) {
291	      const [profile] = await db
292	        .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
293	        .from(userProfilesTable)
294	        .where(eq(userProfilesTable.userId, facility.ownerUserId));
295	      if (profile?.stripeAccountId && profile.status === "active") {
296	        connectAccountId = profile.stripeAccountId;
297	      }
298	    }
299	
300	    const amountCents = Math.round(pricePerSlot * 100);
301	    const sessionParams: any = {
302	      payment_method_types: ["card"],
303	      line_items: [{
304	        price_data: {
305	          currency: "eur",
