991	// ─── sweepHostGuarantees ──────────────────────────────────────────────────────
992	// Runs periodically. Finds awaiting_players split bookings whose game starts
993	// within GUARANTEE_HOURS. Charges the host's saved card for the missing amount.
994	// On success → confirmed. On failure → cancelled + refund all paid participants.
995	
996	const GUARANTEE_HOURS = 2;
997	
998	export async function sweepHostGuarantees(): Promise<number> {
999	  // Find split bookings in awaiting_players whose game starts within the guarantee window
1000	  const candidates = await db
1001	    .select({
1002	      booking: bookingsTable,
1003	      game: gamesTable,
1004	    })
1005	    .from(bookingsTable)
1006	    .innerJoin(gamesTable, eq(gamesTable.bookingId, bookingsTable.id))
1007	    .where(
1008	      and(
1009	        eq(bookingsTable.status, "awaiting_players"),
1010	        eq(bookingsTable.isSplit, true),
1011	        // Only bookings where we have a saved payment method for the host
1012	        sql`${bookingsTable.hostStripeCustomerId} IS NOT NULL`,
1013	        sql`${bookingsTable.hostStripePaymentMethodId} IS NOT NULL`,
1014	        // Game starts within the next GUARANTEE_HOURS (deadline reached)
1015	        sql`CAST(${gamesTable.datetime} AS TIMESTAMPTZ) <= NOW() + INTERVAL '${sql.raw(String(GUARANTEE_HOURS))} hours'`,
1016	        // Game hasn't ended yet (don't process historical bookings)
1017	        sql`CAST(${gamesTable.datetime} AS TIMESTAMPTZ) > NOW() - INTERVAL '3 hours'`,
1018	      ),
1019	    );
1020	
1021	  if (candidates.length === 0) return 0;
1022	
1023	  let processed = 0;
1024	  const stripe = await getUncachableStripeClient().catch(() => null);
1025	  if (!stripe) return 0; // Stripe not configured; skip in dev
1026	
1027	  for (const { booking, game } of candidates) {
1028	    try {
1029	      // Get all participants for this game
1030	      const participants = await db
1031	        .select()
1032	        .from(gameParticipantsTable)
1033	        .where(and(
1034	          eq(gameParticipantsTable.gameId, game.id),
1035	          eq(gameParticipantsTable.status, "joined"),
1036	        ));
1037	
1038	      const paidCount = participants.filter(p => p.paymentStatus === "paid").length;
1039	      const totalSlots = booking.totalSlots ?? 1;
1040	      const pricePerSlot = Number(booking.pricePerSlot ?? 0);
1041	      const missingSlots = Math.max(0, totalSlots - paidCount);
1042	
1043	      if (missingSlots === 0) {
1044	        // All paid — just confirm
1045	        await db.update(bookingsTable).set({ status: "confirmed" }).where(eq(bookingsTable.id, booking.id));
1046	        await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, game.id));
1047	        processed++;
1048	        continue;
1049	      }
1050	
1051	      const missingAmountCents = Math.round(missingSlots * pricePerSlot * 100);
1052	
1053	      // Fetch Connect account if applicable
1054	      let transferData: { destination: string } | undefined;
1055	      let appFeeAmount: number | undefined;
1056	      const courtRows = await db
1057	        .select({ facilityId: courtsTable.facilityId })
1058	        .from(courtsTable)
1059	        .where(eq(courtsTable.id, booking.courtId));
1060	      const facilityId = courtRows[0]?.facilityId;
1061	      if (facilityId) {
1062	        const [fac] = await db
1063	          .select({ ownerUserId: facilitiesTable.ownerUserId })
1064	          .from(facilitiesTable)
1065	          .where(eq(facilitiesTable.id, facilityId));
1066	        if (fac?.ownerUserId) {
1067	          const [profile] = await db
1068	            .select({ stripeAccountId: userProfilesTable.stripeAccountId, status: userProfilesTable.stripeAccountStatus })
1069	            .from(userProfilesTable)
1070	            .where(eq(userProfilesTable.userId, fac.ownerUserId));
1071	          if (profile?.stripeAccountId && profile.status === "active") {
1072	            transferData = { destination: profile.stripeAccountId };
1073	            appFeeAmount = Math.round(missingAmountCents * 5 / 100);
1074	          }
1075	        }
1076	      }
1077	
1078	      try {
1079	        await stripe.paymentIntents.create({
1080	          amount: missingAmountCents,
1081	          currency: "eur",
1082	          customer: booking.hostStripeCustomerId!,
1083	          payment_method: booking.hostStripePaymentMethodId!,
1084	          confirm: true,
1085	          off_session: true,
1086	          ...(transferData ? { transfer_data: transferData, application_fee_amount: appFeeAmount } : {}),
1087	        }, {
1088	          idempotencyKey: `guarantee-booking-${booking.id}`,
1089	        });
1090	
1091	        // Charge succeeded → confirm
1092	        await db.update(bookingsTable).set({ status: "confirmed" }).where(eq(bookingsTable.id, booking.id));
1093	        await db.update(gamesTable).set({ status: "open" }).where(eq(gamesTable.id, game.id));
1094	        logger.info({ bookingId: booking.id, missingAmountCents }, "guarantee charge succeeded");
1095	        processed++;
1096	      } catch (chargeErr: any) {
1097	        // Charge failed → cancel and refund paid participants
1098	        logger.warn({ bookingId: booking.id, err: chargeErr?.message }, "guarantee charge failed — cancelling");
1099	        await db.update(bookingsTable).set({ status: "cancelled" }).where(eq(bookingsTable.id, booking.id));
1100	        await db.update(gamesTable).set({ status: "cancelling" }).where(eq(gamesTable.id, game.id));
1101	
1102	        // Refund each paid participant via their session's payment intent
1103	        const paidParticipants = participants.filter(p => p.paymentStatus === "paid" && p.stripeSessionId);
1104	        for (const p of paidParticipants) {
1105	          try {
1106	            const session = await stripe.checkout.sessions.retrieve(p.stripeSessionId!);
1107	            if (session.payment_intent) {
1108	              await stripe.refunds.create({ payment_intent: session.payment_intent as string });
1109	            }
1110	          } catch (refundErr) {
1111	            logger.error({ participantId: p.id, err: refundErr }, "guarantee refund failed");
1112	          }
1113	        }
1114	        processed++;
1115	      }
1116	    } catch (err) {
1117	      logger.error({ bookingId: booking.id, err }, "sweepHostGuarantees: unexpected error");
1118	    }
1119	  }
1120	
1121	  return processed;
1122	}
