27	// ─── Refund tier policy ──────────────────────────────────────────────────────
28	// >= 48h before start: 80% refund
29	// >= 24h and < 48h:    50% refund
30	// <  24h:              0% refund
31	//
32	// All money math is done in INTEGER CENTS to avoid binary-float rounding (e.g.
33	// 19.99 * 0.5 = 9.995). Stripe `refunds.create.amount` is also in integer cents.
34	export function computeRefund(totalPriceEur: number, hoursBeforeStart: number) {
35	  const totalCents = Math.round(totalPriceEur * 100);
36	  if (hoursBeforeStart >= 48) {
37	    const cents = Math.round(totalCents * 0.80);
38	    return { refundPercent: 80, refundAmount: cents / 100, refundCents: cents, refundable: true };
39	  }
40	  if (hoursBeforeStart >= 24) {
41	    const cents = Math.round(totalCents * 0.50);
42	    return { refundPercent: 50, refundAmount: cents / 100, refundCents: cents, refundable: true };
43	  }
44	  return { refundPercent: 0, refundAmount: 0, refundCents: 0, refundable: false };
45	}
