86	function slotsBetween(startTime: string, endTime: string): string[] {
87	  const start = toMin(startTime);
88	  const end = toMin(endTime);
89	  const result: string[] = [];
90	  for (let m = start; m < end; m += 30) {
91	    const h = Math.floor(m / 60);
92	    const min = m % 60;
93	    result.push(`${h.toString().padStart(2, "0")}:${min.toString().padStart(2, "0")}`);
94	  }
95	  return result;
96	}
