132	/** Generate 30-min slots between openTime and closeTime (default: 07:00–22:00).
133	 *  The last slot ends at closeTime, so a slot starting at closeTime is excluded.
134	 *  E.g. open="08:00", close="22:00" produces 08:00–08:30, …, 21:30–22:00
135	 */
136	function generateSlots(openTime = "07:00", closeTime = "22:00"): { startTime: string; endTime: string }[] {
137	  const openMin = timeToMin(openTime);
138	  const closeMin = timeToMin(closeTime);
139	  const slots = [];
140	  for (let m = openMin; m + 30 <= closeMin; m += 30) {
141	    slots.push({ startTime: minToTime(m), endTime: minToTime(m + 30) });
142	  }
143	  return slots;
144	}
