790	// GET /courts/:id/equipment-availability?date=YYYY-MM-DD&startTime=HH:MM&endTime=HH:MM
791	router.get("/courts/:id/equipment-availability", async (req, res): Promise<void> => {
792	  const courtId = parseInt(String(req.params.id), 10);
793	  const { date, startTime, endTime } = req.query as Record<string, string>;
794	  if (!courtId || !date || !startTime || !endTime) {
795	    res.status(400).json({ error: "courtId, date, startTime, endTime required" });
796	    return;
797	  }
798	
799	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, courtId));
800	  if (!court) { res.status(404).json({ error: "Court not found" }); return; }
801	
802	  const equipment: Array<{ name: string; pricePerSlot: number; stock: number }> =
803	    court.rentableItems ? JSON.parse(court.rentableItems) : [];
804	
805	  if (equipment.length === 0) { res.json([]); return; }
806	
807	  // Find overlapping confirmed/pending bookings with rented items
808	  const existingBookings = await db
809	    .select({ rentedItems: bookingsTable.rentedItems, startTime: bookingsTable.startTime, endTime: bookingsTable.endTime })
810	    .from(bookingsTable)
811	    .where(and(eq(bookingsTable.courtId, courtId), eq(bookingsTable.date, date)));
812	
813	  // Parse startTime/endTime to minutes for overlap check
814	  const toMin = (t: string) => { const [h, m] = t.split(":").map(Number); return h * 60 + m; };
815	  const reqStart = toMin(startTime);
816	  const reqEnd = toMin(endTime);
817	
818	  // Sum up booked quantities for overlapping bookings
819	  const bookedQty: Record<string, number> = {};
820	  for (const b of existingBookings) {
821	    if (!b.rentedItems) continue;
822	    const bStart = toMin(b.startTime);
823	    const bEnd = toMin(b.endTime);
824	    // Overlap: not (bEnd <= reqStart || bStart >= reqEnd)
825	    if (bEnd <= reqStart || bStart >= reqEnd) continue;
826	    try {
827	      const items: Array<{ name: string; quantity: number }> = JSON.parse(b.rentedItems);
828	      for (const item of items) {
829	        bookedQty[item.name] = (bookedQty[item.name] ?? 0) + item.quantity;
830	      }
831	    } catch {}
832	  }
833	
834	  const result = equipment.map(e => ({
835	    name: e.name,
836	    pricePerSlot: e.pricePerSlot,
837	    stock: e.stock,
838	    booked: bookedQty[e.name] ?? 0,
839	    available: Math.max(0, e.stock - (bookedQty[e.name] ?? 0)),
840	  }));
841	
842	  res.json(result);
843	});
