232	    const [prior] = await db
233	      .select()
234	      .from(messagesTable)
235	      .where(and(eq(messagesTable.courtId, courtId), eq(messagesTable.senderUserId, threadUserId)));
236	    recipientUserId = threadUserId;
237	    recipientEmail = prior?.senderEmail ?? null;
238	  } else {
239	    recipientUserId = msgFacility?.ownerUserId ?? null;
240	    recipientEmail = msgFacility?.email ?? null;
241	  }
242	
243	  const [message] = await db.insert(messagesTable).values({
244	    courtId,
245	    senderUserId: senderUserId!,
246	    senderName,
247	    senderEmail,
248	    recipientUserId,
249	    recipientEmail,
250	    subject: isOwner ? "Re: Žinutė nuo savininko" : "Žinutė kortui",
251	    body,
252	  }).returning();
253	
254	  // Fire notification for the recipient
255	  if (recipientUserId) {
