258	      type: "message",
259	      title: isOwner ? `Atsakymas nuo savininko — ${court.name}` : `Nauja žinutė nuo ${senderName}`,
260	      body: body.length > 100 ? body.slice(0, 97) + "…" : body,
261	      link: isOwner ? "/profile" : `/courts/${courtId}`,
262	    }).catch(() => {});
