92	    res.status(400).json({ error: "Invalid booking id" });
93	    return;
94	  }
95	
96	  const parsed = ForceCancelBody.safeParse(req.body);
97	  if (!parsed.success) {
98	    res.status(400).json({ error: parsed.error.message });
99	    return;
100	  }
101	
102	  const userId = getCurrentUserId(req)!;
103	
104	  const rows = await db
105	    .select({
106	      booking: bookingsTable,
107	      courtOwnerUserId: facilitiesTable.ownerUserId,
108	      courtFacilityId: courtsTable.facilityId,
109	      courtName: courtsTable.name,
110	      ownerName: facilitiesTable.name,
111	      ownerEmail: facilitiesTable.email,
112	    })
113	    .from(bookingsTable)
114	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
115	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
116	    .where(eq(bookingsTable.id, id));
117	
118	  if (!rows[0]) {
119	    res.status(404).json({ error: "Booking not found" });
120	    return;
121	  }
122	
123	  const { booking, courtOwnerUserId, courtFacilityId, courtName, ownerName, ownerEmail } = rows[0];
124	
125	  // Ownership check: caller must own the facility.
126	  const isOwner = courtOwnerUserId === userId;
127	  if (!isOwner) {
128	    res.status(403).json({ error: "Forbidden" });
129	    return;
130	  }
131	
132	  if (booking.status === "cancelled") {
133	    res.status(409).json({ error: "Booking is already cancelled" });
134	    return;
135	  }
136	
137	  // Validate refund amount: must not exceed the original totalPrice.
138	  const totalPriceEur = Number(booking.totalPrice);
139	  const totalPriceCents = Math.round(totalPriceEur * 100);
140	  const refundCents = parsed.data.refundAmountCents;
141	  if (refundCents > totalPriceCents) {
142	    res.status(400).json({
143	      error: `Refund amount (${(refundCents / 100).toFixed(2)} €) exceeds booking total (${totalPriceEur.toFixed(2)} €)`,
144	      code: "REFUND_EXCEEDS_TOTAL",
145	    });
146	    return;
147	  }
