216	  // Notify the booker (unless the owner force-cancelled their own booking).
217	  if (booking.bookerUserId && booking.bookerUserId !== userId) {
218	    sendNotification(
219	      booking.bookerUserId,
220	      "booking_cancelled",
221	      `Rezervacija atšaukta — ${displayCourtName}`,
222	      refundEur > 0
223	        ? `Jūsų rezervacija ${dateStr} ${booking.startTime}–${booking.endTime} atšaukta savininko. Grąžinta: ${refundEur.toFixed(2)} €.`
224	        : `Jūsų rezervacija ${dateStr} ${booking.startTime}–${booking.endTime} atšaukta savininko.`,
225	      "/bookings",
226	    ).catch((err) => logger.error({ err, bookingId: id }, "force-cancel booker notification failed"));
227	  }
228	
229	  // Email customer with refund details.
230	  if (booking.customerEmail) {
231	    sendCustomerCancellationEmail({
232	      customerName: booking.customerName,
233	      customerEmail: booking.customerEmail,
234	      courtName: displayCourtName,
235	      date: booking.date,
236	      startTime: booking.startTime,
237	      endTime: booking.endTime,
238	      totalPrice: totalPriceEur,
239	      refundAmount: refundEur,
240	      bookingId: id,
241	    }).catch((err) => logger.error({ err, bookingId: id }, "force-cancel customer email failed"));
242	  }
243	
