1	import { sweepStalePendingGames, sweepAutoConfirmResults } from "../routes/games";
2	import { sweepAbandonedPendingBookings } from "../routes/bookings";
3	import { sweepHostGuarantees } from "../routes/split-payments";
4	import { logger } from "./logger";
5	
6	const TICK_INTERVAL_MS = 60 * 1000;
7	const GUARANTEE_SWEEP_EVERY_N_TICKS = 15; // run guarantee sweep every ~15 minutes
8	
9	export function startCron(): void {
10	  let running = false;
11	  let tickCount = 0;
12	  const tick = async () => {
13	    if (running) return;
14	    running = true;
15	    tickCount++;
16	    try {
17	      const promises: Promise<number>[] = [
18	        sweepStalePendingGames(),
19	        sweepAutoConfirmResults(),
20	        sweepAbandonedPendingBookings(),
21	      ];
22	      if (tickCount % GUARANTEE_SWEEP_EVERY_N_TICKS === 1) {
23	        promises.push(sweepHostGuarantees());
24	      }
25	      const counts = await Promise.all(promises);
26	      const [staleCount, autoCount, abandonedBookingCount, guaranteeCount = 0] = counts;
27	      if (staleCount > 0 || autoCount > 0 || abandonedBookingCount > 0 || guaranteeCount > 0) {
28	        logger.info({ staleCount, autoCount, abandonedBookingCount, guaranteeCount }, "cron: swept");
29	      }
30	    } catch (err) {
31	      logger.error({ err }, "cron tick failed");
32	    } finally {
33	      running = false;
34	    }
35	  };
36	  setInterval(tick, TICK_INTERVAL_MS);
37	  setTimeout(tick, 5000);
38	  logger.info({ intervalMs: TICK_INTERVAL_MS }, "cron started");
39	}
