125	// ─── POST /api/guest/bookings/:token/cancel ──────────────────────────────────
126	// Mirrors DELETE /bookings/:id (atomic CAS + Stripe refund + emails) but
127	// authorized via the management token instead of a Clerk session.
128	router.post("/guest/bookings/:token/cancel", async (req, res): Promise<void> => {
129	  const token = req.params.token;
130	  if (!isPlausibleToken(token)) {
131	    res.status(404).json({ error: "Booking not found" });
132	    return;
133	  }
134	
135	  const rows = await db
136	    .select({
137	      booking: bookingsTable,
138	      courtName: courtsTable.name,
139	      courtOwnerUserId: facilitiesTable.ownerUserId,
140	      ownerName: facilitiesTable.name,
141	      ownerEmail: facilitiesTable.email,
142	    })
143	    .from(bookingsTable)
144	    .leftJoin(courtsTable, eq(bookingsTable.courtId, courtsTable.id))
145	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
146	    .where(eq(bookingsTable.managementToken, token));
147	
148	  if (!rows[0]) {
149	    res.status(404).json({ error: "Booking not found" });
150	    return;
151	  }
152	
153	  const { booking, courtName, courtOwnerUserId, ownerName, ownerEmail } = rows[0];
154	
155	  // Idempotent: if it was already cancelled, just return current state.
156	  if (booking.status === "cancelled") {
157	    res.json({
158	      ...booking,
159	      totalPrice: Number(booking.totalPrice),
160	      refundAmount: Number(booking.refundAmount ?? 0),
161	    });
162	    return;
163	  }
164	
165	  const totalPriceEur = Number(booking.totalPrice);
166	  const hours = hoursBeforeStart(booking.date, booking.startTime);
167	  const tier = computeRefund(totalPriceEur, hours);
168	
169	  if (hours <= 0) {
170	    res.status(400).json({ error: "Booking has already started or ended", code: "CANCEL_TOO_LATE" });
171	    return;
172	  }
173	
174	  // Atomic compare-and-set on status to prevent double-refund races.
175	  const claimed = await db
176	    .update(bookingsTable)
177	    .set({ status: "cancelled" })
178	    .where(and(eq(bookingsTable.id, booking.id), ne(bookingsTable.status, "cancelled")))
179	    .returning();
180	
181	  if (claimed.length === 0) {
182	    const [current] = await db.select().from(bookingsTable).where(eq(bookingsTable.id, booking.id));
183	    res.json({
184	      ...current,
185	      totalPrice: Number(current.totalPrice),
186	      refundAmount: Number(current.refundAmount ?? 0),
187	    });
188	    return;
189	  }
190	
191	  let stripeRefundId: string | null = null;
192	  if (
193	    tier.refundable &&
194	    tier.refundAmount > 0 &&
195	    booking.stripePaymentIntentId &&
196	    !booking.stripePaymentIntentId.startsWith("mock_")
197	  ) {
198	    try {
199	      const stripe = await getUncachableStripeClient();
200	      const refund = await stripe.refunds.create(
201	        {
202	          payment_intent: booking.stripePaymentIntentId,
203	          amount: Math.round(tier.refundAmount * 100),
204	          reason: "requested_by_customer",
205	        },
206	        // Same idempotency key as the authed path so retries from any surface dedupe.
207	        { idempotencyKey: `cancel-booking-${booking.id}` },
208	      );
209	      stripeRefundId = refund.id;
210	      logger.info(
211	        { bookingId: booking.id, refundId: refund.id, amount: tier.refundAmount, source: "guest" },
212	        "Stripe refund issued (guest cancel)",
213	      );
214	    } catch (err) {
215	      logger.error({ err, bookingId: booking.id, source: "guest" }, "Stripe refund failed (guest cancel)");
216	      // Roll back the status transition so support can retry.
217	      await db
218	        .update(bookingsTable)
219	        .set({ status: booking.status })
220	        .where(eq(bookingsTable.id, booking.id));
221	      res.status(502).json({ error: "Refund failed at payment provider" });
222	      return;
223	    }
224	  }
225	
226	  const [cancelled] = await db
227	    .update(bookingsTable)
228	    .set({
229	      refundAmount: String(tier.refundAmount),
230	      stripeRefundId,
231	    })
232	    .where(eq(bookingsTable.id, booking.id))
233	    .returning();
234	
235	  // ─── Notifications (fire-and-forget) ─────────────────────────────────────
236	  const displayCourtName = courtName ?? "Kortas";
237	  const dateStr = String(booking.date);
238	
239	  if (courtOwnerUserId) {
240	    sendNotification(
241	      courtOwnerUserId,
242	      "booking_cancelled",
243	      `Atšaukta rezervacija — ${displayCourtName}`,
244	      `${booking.customerName} (svečias) atšaukė ${dateStr} ${booking.startTime}–${booking.endTime}.${
245	        tier.refundAmount > 0 ? ` Grąžinta klientui: ${tier.refundAmount.toFixed(2)} €.` : ""
246	      }`,
247	      "/owner",
248	    ).catch((err) => logger.error({ err, bookingId: booking.id }, "owner cancel notification failed (guest)"));
249	  }
250	
251	  if (booking.customerEmail) {
252	    sendCustomerCancellationEmail({
253	      customerName: booking.customerName,
254	      customerEmail: booking.customerEmail,
255	      courtName: displayCourtName,
256	      date: booking.date,
257	      startTime: booking.startTime,
258	      endTime: booking.endTime,
259	      totalPrice: totalPriceEur,
260	      refundAmount: tier.refundAmount,
261	      bookingId: booking.id,
262	    }).catch((err) => logger.error({ err, bookingId: booking.id }, "sendCustomerCancellationEmail failed (guest)"));
263	  }
264	
265	  if (ownerEmail) {
266	    sendOwnerCancellationEmail({
267	      ownerName: ownerName ?? "Savininkas",
268	      ownerEmail,
269	      customerName: booking.customerName,
270	      courtName: displayCourtName,
271	      date: booking.date,
272	      startTime: booking.startTime,
273	      endTime: booking.endTime,
274	      totalPrice: totalPriceEur,
275	      refundAmount: tier.refundAmount,
276	      bookingId: booking.id,
277	    }).catch((err) => logger.error({ err, bookingId: booking.id }, "sendOwnerCancellationEmail failed (guest)"));
278	  }
279	
280	  res.json({
281	    ...cancelled,
282	    totalPrice: Number(cancelled.totalPrice),
283	    refundAmount: Number(cancelled.refundAmount ?? 0),
284	    refundPercent: tier.refundPercent,
285	  });
286	});
