1	// Helpers for guest-booking management tokens.
2	// All comparisons must be timing-safe: tokens authorize publicly-reachable
3	// endpoints (cancel/confirm/refund) so naive `===` would leak character-by-
4	// character timing information about valid tokens.
5	
6	import { timingSafeEqual } from "node:crypto";
7	
8	// Defensive guard: block tokens that are obviously not real to avoid wasting
9	// DB queries (and to make timing-attack discovery slightly harder).
10	export function isPlausibleToken(token: string | undefined | null): token is string {
11	  return typeof token === "string" && token.length >= 16 && token.length <= 128;
12	}
13	
14	// Constant-time token equality. `a` is the user-supplied value; `b` is the
15	// expected token from the DB. Returns false fast if either side is missing or
16	// lengths differ (length-mismatch alone is not a secret leak — the prefix
17	// space of valid tokens is fixed by `randomBytes(32).toString("base64url")`).
18	export function timingSafeEqualToken(a: string | undefined | null, b: string | undefined | null): boolean {
19	  if (typeof a !== "string" || typeof b !== "string") return false;
20	  if (a.length !== b.length) return false;
21	  const aBuf = Buffer.from(a, "utf8");
22	  const bBuf = Buffer.from(b, "utf8");
23	  if (aBuf.length !== bBuf.length) return false;
24	  return timingSafeEqual(aBuf, bBuf);
25	}
